<?php get_header(); while(have_posts()): the_post(); $id=get_the_ID(); ?><div class="container"><div class="page-head"><div class="breadcrumb"><a href="<?php echo esc_url(classs_link('projects')); ?>">Projects</a> / <?php the_title(); ?></div></div><section class="detail"><div class="detail-img"><?php echo classs_picture($id); ?></div><div><span class="eyebrow"><?php echo esc_html(get_post_meta($id,'classs_technology',true)); ?></span><h1><?php the_title(); ?></h1><div><?php the_content(); ?></div><div class="specs"><?php foreach(['branch'=>'Branch','difficulty'=>'Difficulty','technology'=>'Technology','budget'=>'Indicative budget (₹)'] as $key=>$label) echo '<div><span>'.esc_html($label).'</span>'.esc_html(get_post_meta($id,'classs_'.$key,true)).'</div>'; ?></div><a class="btn blue" href="#request">Request this project</a><?php $phone=preg_replace('/\D/','',get_option('classs_whatsapp','')); if($phone): ?><a class="btn outline" target="_blank" rel="noopener" href="<?php echo esc_url('https://wa.me/'.$phone.'?text='.rawurlencode('Hi CLASSS Projects, I am interested in '.get_the_title())); ?>">WhatsApp enquiry</a><?php endif; ?></div></section><section class="section"><h2>How it works</h2><p><?php echo esc_html(get_post_meta($id,'classs_how',true)); ?></p><h2>Applications</h2><p><?php echo esc_html(get_post_meta($id,'classs_applications',true)); ?></p><h2>Components</h2><div class="grid"><?php foreach(array_filter(array_map('absint',explode(',',get_post_meta($id,'classs_components',true)))) as $pid) classs_product_card($pid); ?></div><?php $video=get_post_meta($id,'classs_video',true); if($video): ?><h2 style="margin-top:30px">Project video</h2><?php echo wp_kses_post(wp_oembed_get($video)); endif; $doc=get_post_meta($id,'classs_document',true); if($doc): ?><p><a class="btn outline" href="<?php echo esc_url($doc); ?>">Project document</a></p><?php endif; ?><div id="request" class="panel" style="margin-top:35px"><h2>Tell us about your build.</h2><?php echo do_shortcode('[classs_request_form kind="Project"]'); ?></div></section></div><?php endwhile; get_footer(); ?>
